using System;
using System.Globalization;
using System.Text;
using UnityEngine;
using UnityEngine.Networking;

namespace SrtpAvatar
{
    // Decodes SSE transport separately from the JSON object generated by the model.
    public sealed class DialogueStreamDecoder
    {
        private readonly Action<string> onSentence;
        private readonly Decoder utf8 = Encoding.UTF8.GetDecoder();
        private readonly StringBuilder wire = new StringBuilder();
        private readonly StringBuilder line = new StringBuilder();
        private readonly StringBuilder eventData = new StringBuilder();
        private readonly StringBuilder content = new StringBuilder();
        private char[] characters = new char[4096];
        private int emittedCharacters;
        private string previousReply = "";
        private bool receivedEvent;
        private bool done;
        public string Content => content.ToString();
        public string ReplyText { get; private set; } = "";
        public bool Truncated { get; private set; }

        public DialogueStreamDecoder(Action<string> onSentence) { this.onSentence = onSentence; }
        public void Append(byte[] bytes, int count)
        {
            var required = Encoding.UTF8.GetMaxCharCount(count);
            if (characters.Length < required) characters = new char[required];
            var length = utf8.GetChars(bytes, 0, count, characters, 0, false);
            wire.Append(characters, 0, length);
            for (var i = 0; i < length; i++)
            {
                var character = characters[i];
                if (character == '\n') { ProcessLine(line.ToString().TrimEnd('\r')); line.Clear(); }
                else line.Append(character);
            }
        }
        private void ProcessLine(string value)
        {
            if (value.Length == 0) { DispatchEvent(); return; }
            if (!value.StartsWith("data:", StringComparison.Ordinal)) return;
            if (eventData.Length > 0) eventData.Append('\n');
            eventData.Append(value.Substring(5).TrimStart());
        }
        private void DispatchEvent()
        {
            if (eventData.Length == 0 || done) return;
            var payload = eventData.ToString();
            eventData.Clear();
            receivedEvent = true;
            if (payload == "[DONE]") { done = true; return; }
            var chunk = JsonUtility.FromJson<CompletionChunk>(payload);
            if (chunk?.choices == null || chunk.choices.Length == 0) return;
            var choice = chunk.choices[0];
            Truncated |= choice.finish_reason == "length";
            content.Append(choice.delta?.content);
            EmitAvailableReply();
        }
        public void Finish()
        {
            if (line.Length > 0) ProcessLine(line.ToString().TrimEnd('\r'));
            DispatchEvent();
            if (!receivedEvent)
            {
                // Some compatible providers ignore stream=true and return a complete object.
                var response = JsonUtility.FromJson<CompletionChunk>(wire.ToString());
                if (response?.choices != null && response.choices.Length > 0)
                {
                    content.Append(response.choices[0].message?.content);
                    Truncated = response.choices[0].finish_reason == "length";
                    EmitAvailableReply();
                }
            }
            else if (!done) throw new FormatException("The dialogue stream ended before its completion marker.");
            if (Truncated) throw new FormatException("The dialogue response exceeded its token limit.");
        }
        public DialogueDecision CompleteDecision()
        {
            try { Finish(); }
            catch (Exception ex) when (ex is FormatException || ex is ArgumentException)
            {
                throw new AppException(AppErr.badJson, "流式回复未完整返回。", ex);
            }
            if (!DialogueParser.TryFromPossiblyWrappedJson(Content, out var decision))
                throw new AppException(AppErr.badJson, "对话服务返回的 JSON 格式无效或内容为空。");
            if (!string.Equals(ReplyText.Trim(), decision.reply.Trim(), StringComparison.Ordinal))
                throw new AppException(AppErr.badJson, "流式回复内容不一致。");
            return decision;
        }

        private void EmitAvailableReply()
        {
            if (!TryReadReply(content.ToString(), out var prefix, out var closed)) return;
            if (!prefix.StartsWith(previousReply, StringComparison.Ordinal)) throw new FormatException("Reply changed during streaming.");
            previousReply = ReplyText = prefix;
            var start = emittedCharacters;
            for (var i = start; i < prefix.Length; i++)
            {
                if ("。！？!?；;\n".IndexOf(prefix[i]) < 0) continue;
                Emit(prefix, i + 1);
            }
            if (closed && emittedCharacters < prefix.Length) Emit(prefix, prefix.Length);
        }
        private void Emit(string prefix, int end)
        {
            var sentence = prefix.Substring(emittedCharacters, end - emittedCharacters);
            emittedCharacters = end;
            if (!string.IsNullOrWhiteSpace(sentence)) onSentence?.Invoke(sentence);
        }
        private static bool TryReadReply(string json, out string reply, out bool closed)
        {
            reply = "";
            closed = false;
            var depth = 0;
            for (var i = 0; i < json.Length; i++)
            {
                var value = json[i];
                if (value == '{' || value == '[') { depth++; continue; }
                if (value == '}' || value == ']') { depth--; continue; }
                if (value != '"') continue;
                var token = ReadString(json, ref i, out var tokenClosed);
                if (!tokenClosed) return false;
                if (depth != 1 || token != "reply") continue;
                var next = i + 1;
                while (next < json.Length && char.IsWhiteSpace(json[next])) next++;
                if (next >= json.Length || json[next++] != ':') continue;
                while (next < json.Length && char.IsWhiteSpace(json[next])) next++;
                if (next >= json.Length || json[next] != '"') return false;
                reply = ReadString(json, ref next, out closed);
                return true;
            }
            return false;
        }
        private static string ReadString(string json, ref int index, out bool closed)
        {
            var output = new StringBuilder();
            closed = false;
            for (index++; index < json.Length; index++)
            {
                var value = json[index];
                if (value == '"') { closed = true; break; }
                if (value != '\\') { output.Append(value); continue; }
                if (++index >= json.Length) break;
                switch (json[index])
                {
                    case '"': output.Append('"'); break;
                    case '\\': output.Append('\\'); break;
                    case '/': output.Append('/'); break;
                    case 'n': output.Append('\n'); break;
                    case 'r': output.Append('\r'); break;
                    case 't': output.Append('\t'); break;
                    case 'b': output.Append('\b'); break;
                    case 'f': output.Append('\f'); break;
                    case 'u':
                        if (index + 4 >= json.Length) { index = json.Length; break; }
                        output.Append((char)int.Parse(json.Substring(index + 1, 4), NumberStyles.HexNumber, CultureInfo.InvariantCulture));
                        index += 4;
                        break;
                    default: throw new FormatException("Invalid JSON string escape.");
                }
            }
            if (!closed && output.Length > 0 && char.IsHighSurrogate(output[output.Length - 1])) output.Length--;
            return output.ToString();
        }
        [Serializable] private sealed class CompletionChunk { public Choice[] choices; }
        [Serializable] private sealed class Choice { public Message delta; public Message message; public string finish_reason; }
        [Serializable] private sealed class Message { public string content; }
    }

    internal sealed class DialogueStreamDownloadHandler : DownloadHandlerScript
    {
        private readonly DialogueStreamDecoder decoder;
        public Exception Failure { get; private set; }
        public DialogueStreamDownloadHandler(DialogueStreamDecoder decoder) : base(new byte[8192]) { this.decoder = decoder; }
        protected override bool ReceiveData(byte[] data, int dataLength)
        {
            try { decoder.Append(data, dataLength); return true; }
            catch (Exception ex) { Failure = ex; return false; }
        }
    }
}